/* @lc app=leetcode id=4012 lang=kotlin */ class Solution { fun countTasks(tasks: IntArray, shifts: IntArray): IntArray = tasks.runningFold(0L) { a, b -> a + b }.let { pre -> pre.last().let { S -> shifts.fold(0L to ArrayList<Int>()) { (c, out), s -> (c + s).let { nc -> if (nc >= S) 0L to out.also { it.add(0) } else nc to out.also { o -> o.add(tasks.size - pre.binarySearch(nc + 1).let { if (it < 0) -it - 1 else it } + 1) } } }.second.toIntArray() } } }